const { useState } = React;

function ProductForm() {
  const [form, setForm] = useState({ name: '', price: '' });

  function handleChange(event) {
    const { name, value } = event.currentTarget;
    setForm((previous) => ({
      ...previous,
      [name]: value,
    }));
  }

  return (
    <form>
      <label>상품 이름 <input name="name" value={form.name} onChange={handleChange} /></label>
      <label>가격 <input name="price" value={form.price} onChange={handleChange} /></label>
      <p>{form.name || '상품'} / {form.price || '0'}원</p>
    </form>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<ProductForm />);

